function progress(course){return Math.min(100,Math.round(new Set(state.completed[course.id]||[]).size/course.lessons*100));}
function activityAdd(title,meta,xp,kind='file'){state.activity.unshift({title,meta:`${meta} · только что`,xp,icon:kind,color:kind==='circleCheck'?'':'yellow',date:new Date().toISOString()});state.activity=state.activity.slice(0,80);state.xp+=xp;state.notificationsRead=false;save();updateHeader()}
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=icon('circleCheck')+`<span>${escapeHTML(message)}</span>`;$('#toast-root').append(el);setTimeout(()=>el.remove(),4200)}
function updateHeader(){document.documentElement.dataset.theme=state.theme;$('.theme-button').innerHTML=icon('sun',21);$('.theme-button').setAttribute('aria-label',state.theme==='light'?'Включить тёмную тему':'Включить светлую тему');$('#header-name').textContent=`${state.profile.name} ${String(state.profile.surname).slice(0,1)}.`;$$('.avatar').forEach(el=>el.textContent=(String(state.profile.name).slice(0,1)+String(state.profile.surname).slice(0,1)).toUpperCase());$('.notification-button').innerHTML=icon('bell',20)+(state.notificationsRead?'':'<i class="notification-dot"></i>');$('.profile-text small').textContent=state.premium?'Студент · Pro':'Студент';$('.premium-card h3').textContent=state.premium?'Премиум активен':'Премиум-доступ';$('.premium-card .button').innerHTML=icon('crown',15)+(state.premium?'Мой тариф':'Оформить')}
