function pageHeading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function empty(title,text,action=''){return `<div class="empty-state">${icon('search',34)}<h3>${title}</h3><p>${text}</p>${action}</div>`}
function bar(value){return `<div class="progress-track" role="progressbar" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="100" aria-label="Прогресс обучения"><i style="--value:${value}%"></i></div>`}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 280 190" aria-hidden="true"><defs><linearGradient id="screen" x1="0" x2="1" y2="1"><stop stop-color="#fff179"/><stop offset=".6" stop-color="#ffdb00"/><stop offset="1" stop-color="#e1b500"/></linearGradient><linearGradient id="mug" x1="0" x2="1"><stop stop-color="#ffe960"/><stop offset=".55" stop-color="#ffe300"/><stop offset="1" stop-color="#dcb000"/></linearGradient><linearGradient id="laptop" y2="1" x2=".5"><stop stop-color="#fffcb4"/><stop offset="1" stop-color="#d7b80e"/></linearGradient><filter id="blur"><feGaussianBlur stdDeviation="5"/></filter></defs><ellipse cx="173" cy="166" rx="99" ry="9" fill="#c9a600" opacity=".15" filter="url(#blur)"/><path d="m98 38 112-22 20 101-107 24Z" fill="#f3cf00"/><path d="m104 43 100-20 18 88-96 23Z" fill="url(#screen)"/><path d="m123 140 107-23 36 30-114 31-60-30Z" fill="url(#laptop)"/><path d="m129 141 96-20 23 22-99 25Z" fill="#f6d83a" stroke="#ffef8a"/><g stroke="#fff8b4" stroke-width="2" opacity=".85"><path d="m115 54 15-3m5-1 32-6m-50 16 44-9m-42 16 20-4m5-1 41-8m-65 20 49-10m-47 17 12-2m5-1 42-8m-57 18 31-6m-29 13 52-10m-50 17 17-3m5-1 27-5"/><path d="m135 143 93-18m-85 24 93-18m-85 24 93-18m-85 24 93-18" stroke-width="1"/></g><path d="m157 162 32-7 8 6-32 9Z" fill="#fff09b"/><path d="M235 98c32-5 30 34 6 35" fill="none" stroke="#e6ba00" stroke-width="9"/><path d="M235 98c28-3 25 28 7 30" fill="none" stroke="#ffe741" stroke-width="4"/><path d="M205 92v48c0 12 43 12 43 0V92Z" fill="url(#mug)"/><ellipse cx="226.5" cy="92" rx="21.5" ry="7" fill="#fff479"/><ellipse cx="226.5" cy="92" rx="18" ry="4.5" fill="#a98800"/><path d="m220 109-6 6 6 5m13-12 6 5-5 6m-7-14-3 18" stroke="#806c00" stroke-width="2" fill="none" stroke-linecap="round"/><ellipse cx="73" cy="155" rx="18" ry="4" fill="#dec222" opacity=".15"/><path d="m60 130 4 25q10 5 19-1l3-25" fill="url(#mug)"/><ellipse cx="73" cy="130" rx="13" ry="4" fill="#f8db39"/><path d="M73 129v-39m0 29c-15-5-18-20-12-21 6-2 7 16 12 15m1-10c1-15 2-25 7-22 6 4-2 19-7 25m0 19c17-4 22-18 16-20-5-2-10 13-16 14" stroke="#e8c635" stroke-width="5" fill="none" stroke-linecap="round"/></svg>`}
function activityHTML(item){return `<div class="activity"><span class="activity-icon ${item.color}">${icon(item.icon,19)}</span><div class="activity-copy"><b>${escapeHTML(item.title)}</b><small>${escapeHTML(item.date?item.meta.split(' · ')[0]+' · '+new Date(item.date).toLocaleDateString('ru-RU'):item.meta)}</small></div><span class="xp">+${item.xp} XP</span></div>`}
function smallCourse(course,index){const p=progress(course);return `<article class="course-card ${index===0?'featured':''}"><button class="course-more" data-action="course-info" data-id="${course.id}" aria-label="Подробнее о курсе ${escapeHTML(course.title)}">⋮</button><div class="course-logo">${logo(course.id)}</div><h3>${escapeHTML(course.title)}</h3><p>${escapeHTML(course.subtitle)}</p><div class="course-progress"><span>${p}%</span>${bar(p)}</div><a class="button soft" href="#/lesson/${course.id}">${p===100?'Повторить':'Продолжить'}</a></article>`}
function chartHTML(course){const values=[12,36,31,51,43,61,70,progress(course)];const points=values.map((v,i)=>[42+i*68,138-v*1.15]);return `<svg class="chart" preserveAspectRatio="none" viewBox="0 0 550 175" role="img" aria-label="Прогресс по курсу ${escapeHTML(course.subtitle)} за восемь недель: ${values.join(', ')} процентов"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ffdc00" stop-opacity=".22"/><stop offset="1" stop-color="#ffdc00" stop-opacity="0"/></linearGradient></defs>${[0,25,50,75,100].map(v=>`<line class="grid-line" x1="40" x2="533" y1="${138-v*1.15}" y2="${138-v*1.15}"/><text x="7" y="${142-v*1.15}">${v}%</text>`).join('')}${points.map((p,i)=>`<line class="grid-line" x1="${p[0]}" x2="${p[0]}" y1="23" y2="141"/><text x="${p[0]}" y="164" text-anchor="middle">Нед ${i+1}</text>`).join('')}<path d="M42 138 ${points.map(p=>'L'+p.join(' ')).join(' ')} L518 138Z" fill="url(#chart-fill)"/><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#e7c300" stroke-width="2"/>${points.map((p,i)=>`<circle class="chart-point" cx="${p[0]}" cy="${p[1]}" r="3"><title>Неделя ${i+1}: ${values[i]}%</title></circle>`).join('')}<rect x="501" y="${Math.max(1,points[7][1]-37)}" width="36" height="29" rx="4" fill="#ffdc00"/><text x="519" y="${Math.max(1,points[7][1]-37)+12}" text-anchor="middle" style="fill:#655711;font-weight:800">${values[7]}%</text><text x="519" y="${Math.max(1,points[7][1]-37)+23}" text-anchor="middle" style="fill:#655711;font-size:8px">Нед 8</text></svg>`}
function homePage(){if(!courses.length)return pageHeading('Добро пожаловать в LogicKernel','Курсы скоро появятся.')+empty('Каталог пока пуст','После публикации материалов они появятся здесь.');const active=courses.filter(c=>state.enrolled.includes(c.id));const featured=active[0]||courses[0];const chartCourses=active.length?active:courses;const p=progress(featured);const overall=Math.min(100,68+Object.values(state.completed).flat().length);return `<div class="dashboard"><section class="panel hero"><div class="hero-copy"><h1>Добро пожаловать, ${escapeHTML(state.profile.name)}! <span class="wave">👋</span></h1><p>Продолжайте обучение и открывайте новых высот в программировании.</p></div>${heroArt()}</section><section class="panel progress-panel"><h2>Общий прогресс</h2><div class="progress-overview"><div class="ring" style="--progress:${overall*2.83}"><svg viewBox="0 0 110 110"><circle cx="55" cy="55" r="45"/><circle class="value" cx="55" cy="55" r="45"/></svg><strong>${overall}%</strong></div><div class="stat-list"><div class="mini-stat">${icon('task')}<div><b>${active.filter(c=>progress(c)<100).length}</b><small>Курса в процессе</small></div></div><div class="mini-stat">${icon('task')}<div><b>${27+state.solved.length}</b><small>Задач решено</small></div></div><div class="mini-stat">${icon('clock')}<div><b>${12+Math.floor(Object.values(state.completed).flat().length/3)}</b><small>Дней подряд</small></div></div></div></div></section><section class="panel courses-panel"><div class="panel-heading"><h2>Мои активные курсы</h2><a class="text-link" href="#/courses">Все курсы ${icon('arrow',13)}</a></div><div class="course-grid">${active.slice(0,4).map(smallCourse).join('')}</div></section><section class="panel activity-panel"><div class="panel-heading"><h2>Недавняя активность</h2><a class="text-link" href="#/activity">Вся активность ${icon('arrow',12)}</a></div><div class="activity-list">${[...state.activity,...initialActivity].slice(0,4).map(activityHTML).join('')}</div></section><section class="panel chart-panel"><div class="panel-heading"><h2 id="chart-title">Прогресс курса: ${escapeHTML(featured.subtitle)}</h2><label class="chart-filter"><span class="tiny-logo" id="chart-logo">${logo(featured.id)}</span><select id="chart-course" aria-label="Курс для графика">${chartCourses.map(c=>`<option value="${c.id}">${escapeHTML(c.subtitle)}</option>`).join('')}</select></label></div><div id="chart-container">${chartHTML(featured)}</div><div class="chart-note"><span>${icon('book',26)}</span><div><b>Вы на правильном пути!</b><p>Продолжайте обучение, чтобы достичь новых результатов.</p></div></div></section><section class="panel continue-panel"><h2>Продолжить обучение</h2><div class="continue-course"><div class="continue-top"><div class="course-logo">${logo(featured.id)}</div><div class="continue-details"><b>${escapeHTML(featured.title)}</b><small>${escapeHTML(featured.subtitle)}</small><div class="continue-progress">${bar(p)}<b>${p}%</b></div></div></div><a href="#/lesson/${featured.id}" class="button primary">${icon('play',15)}Продолжить</a></div><a class="lesson-link" href="#/course/${featured.id}">${icon('book',17)}<span><small>Программа курса</small><b>${escapeHTML(featured.subtitle)}</b></span>${icon('chevron',14)}</a></section></div>`}
function catalogCards(){const filtered=courses.filter(c=>(courseFilter==='all'||courseFilter==='my'&&state.enrolled.includes(c.id)||c.category===courseFilter)&&(c.title+' '+c.subtitle+' '+c.description).toLowerCase().includes(courseQuery.toLowerCase()));return filtered.length?filtered.map(c=>`<article class="panel catalog-card"><div class="catalog-cover"><span class="badge ${c.level==='Средний'?'purple':''}">${escapeHTML(c.level)}</span>${logo(c.id)}</div><div class="catalog-content"><h3>${escapeHTML(c.subtitle)}</h3><p>${escapeHTML(c.description)}</p><div class="catalog-meta"><span>${icon('book',14)}${c.lessons} уроков</span><span>${icon('clock',14)}${c.hours} часов</span></div>${state.enrolled.includes(c.id)?`<div class="continue-progress">${bar(progress(c))}<b>${progress(c)}%</b></div><a class="button primary" href="#/lesson/${c.id}">${icon('play',14)}${progress(c)===100?'Повторить курс':'Продолжить обучение'}</a>`:`<button class="button secondary" data-action="enroll" data-id="${c.id}">Начать бесплатно ${icon('arrow',14)}</button>`}</div><a class="catalog-syllabus" href="#/course/${c.id}">Программа курса ${icon('arrow',13)}</a></article>`).join(''):empty('Курсы не найдены','Попробуйте изменить запрос или выбрать другую категорию.');}
function coursesPage(){return pageHeading('Каталог курсов','Новые знания — новые возможности. Найдите свой следующий шаг.',`<span class="badge">${state.enrolled.length} курса в обучении</span>`)+`<div class="toolbar"><div class="chips">${[['all','Все курсы'],['my','Мои курсы'],['frontend','Frontend'],['backend','Backend'],['fundamentals','Алгоритмы'],['systems','Системные языки']].map(([id,label])=>`<button class="chip ${courseFilter===id?'active':''}" data-action="course-filter" data-id="${id}">${label}</button>`).join('')}</div><input id="course-search" type="search" placeholder="Найти курс…" aria-label="Поиск курсов" value="${escapeHTML(courseQuery)}"></div><div class="catalog-grid" id="catalog-grid">${catalogCards()}</div>`}
function tasksPage(){const filtered=tasks.filter(t=>taskFilter==='all'||taskFilter==='done'&&state.solved.includes(t.id)||taskFilter==='open'&&!state.solved.includes(t.id)||t.level===taskFilter);return pageHeading('Практика делает лучше','Решайте задачи, проверяйте свой код и превращайте знания в навык.')+`<div class="stats-row"><div class="panel stat-card"><small>Задач решено</small><strong>${27+state.solved.length}<span>за всё время</span></strong></div><div class="panel stat-card"><small>Ваш опыт</small><strong>${state.xp.toLocaleString('ru-RU')}<span>XP</span></strong></div><div class="panel stat-card"><small>Серия занятий</small><strong>12<span>дней подряд 🔥</span></strong></div><div class="panel stat-card"><small>Практика JavaScript</small><strong>${state.solved.length}<span>из ${tasks.length} задач</span></strong></div></div><div class="toolbar"><div class="chips">${[['all','Все задачи'],['open','Не решённые'],['done','Решённые'],['Лёгкая','Лёгкие'],['Средняя','Средние'],['Сложная','Сложные']].map(([id,label])=>`<button class="chip ${taskFilter===id?'active':''}" data-action="task-filter" data-id="${id}">${label}</button>`).join('')}</div><span class="badge gray">JavaScript · практика</span></div><div class="panel table-panel">${filtered.length?`<table class="task-table"><thead><tr><th>Задача</th><th>Сложность</th><th>Награда</th><th></th></tr></thead><tbody>${filtered.map(t=>`<tr><td><span class="task-status ${state.solved.includes(t.id)?'done':''}">${icon(state.solved.includes(t.id)?'check':'code',15)}</span><div><strong>${t.title}</strong><small>JavaScript · ${t.topic}</small></div></td><td><span class="badge ${t.level==='Лёгкая'?'green':t.level==='Средняя'?'':'purple'}">${t.level}</span></td><td><span class="xp">+${t.xp} XP</span></td><td><a class="button ${state.solved.includes(t.id)?'secondary':'soft'}" href="#/task/${t.id}">${state.solved.includes(t.id)?'Повторить':'Решить'} ${icon('arrow',13)}</a></td></tr>`).join('')}</tbody></table>`:empty('Здесь пока пусто','Решите первую задачу — и она появится в этом списке.',`<button class="button primary" data-action="task-filter" data-id="all">Ко всем задачам</button>`)}</div><div class="chart-note">${icon('code',23)}<div><b>Практика программирования</b><p>${LKApi.mode==='mock'?'Проект ещё в разработке, отправка решений пока недоступна':'Отправьте решение и получите результат проверки'}</p></div></div>`}
function certificatesPage(){const completed=courses.filter(c=>progress(c)===100);return pageHeading('Ваши сертификаты','Каждый завершённый курс — подтверждение ваших знаний.',`<span class="badge">${1+completed.length} получено</span>`)+`<div class="certificate-grid">${certificateCard('intro','Введение в программирование',true)}${courses.filter(c=>state.enrolled.includes(c.id)).map(c=>certificateCard(c.id,c.subtitle,progress(c)===100)).join('')}</div>`}
function certificateCard(id,title,unlocked){return `<article class="panel ${unlocked?'':'locked'}"><div class="certificate-art"><div class="brand"><span class="brand-code">&lt;/&gt;</span><span>Logic<strong>Kernel</strong></span></div><h3>СЕРТИФИКАТ</h3><p>о прохождении курса</p><b>${title}</b><p>${escapeHTML(state.profile.name+' '+state.profile.surname)}</p><span class="seal">${icon(unlocked?'award':'lock',32)}</span></div><div class="certificate-info"><div><h3>${title}</h3><small>${unlocked?'Курс завершён · '+(id==='intro'?'10 сентября 2026':new Date().toLocaleDateString('ru-RU')):'Завершите курс, чтобы получить сертификат'}</small></div>${unlocked?`<button class="button soft" data-action="certificate" data-id="${id}">${icon('download',15)}Скачать</button>`:`<a class="button secondary" href="#/lesson/${id}">Продолжить</a>`}</div></article>`}
function achievementsPage(){const finished=courses.filter(c=>progress(c)===100).length;const items=[['Первые шаги','Начните своё первое обучение','star',1,1,200],['В ритме','Занимайтесь 7 дней подряд','fire',7,7,300],['Решатель','Решите 25 практических задач','code',27+state.solved.length,25,400],['Любознательность','Начните 4 разных курса','book',state.enrolled.length,4,250],['Марафонец','Занимайтесь 30 дней подряд','trophy',12,30,1000],['Мастер JavaScript','Решите все 6 задач в тренажёре','code',state.solved.length,6,500],['На финишной прямой','Завершите ещё один курс','award',finished,1,600],['Своя библиотека','Сохраните 5 полезных материалов','bookmark',state.bookmarks.length,5,200],['Большая цель','Наберите 5 000 очков опыта','crown',state.xp,5000,750]];return pageHeading('Маленькие победы. Большой прогресс.','Ваши достижения — история того, как вы становитесь лучше.',`<span class="badge">${items.filter(i=>i[3]>=i[4]).length} из ${items.length} открыто</span>`)+`<div class="achievements-grid">${items.map(([title,desc,kind,val,max,xp])=>`<article class="panel achievement-card ${val>=max?'':'locked'}"><div class="achievement-medal">${icon(kind,32)}</div><h3>${title}</h3><p>${desc}</p>${val>=max?`<span class="badge green">${icon('check',11)} Открыто</span>`:`${bar(Math.min(100,Math.round(val/max*100)))}<small>${Math.min(val,max).toLocaleString('ru-RU')} / ${max.toLocaleString('ru-RU')}</small>`}<div><span class="badge gray">${xp} очков достижения</span></div></article>`).join('')}</div><p class="demo-note" style="margin-top:18px">Очки достижений показывают ценность награды. В демоверсии XP начисляется за пройденные уроки и решённые задачи.</p>`}
function resourceCards(){const filtered=resources.filter(r=>(libraryFilter==='all'||libraryFilter==='saved'&&state.bookmarks.includes(r.id)||r.type===libraryFilter)&&(r.title+' '+r.description).toLowerCase().includes(libraryQuery.toLowerCase()));return filtered.length?filtered.map(r=>`<article class="panel resource-card"><div class="resource-top"><span class="resource-icon">${icon(r.type==='Гайд'?'book':r.type==='Статья'?'file':'code',23)}</span><button class="icon-button bookmark ${state.bookmarks.includes(r.id)?'saved':''}" data-action="bookmark" data-id="${r.id}" aria-label="${state.bookmarks.includes(r.id)?'Удалить из избранного':'Сохранить материал'}" aria-pressed="${state.bookmarks.includes(r.id)}">${icon('bookmark')}</button></div><h3>${r.title}</h3><p>${r.description}</p><div class="resource-footer"><span class="badge gray">${r.type} · ${r.time}</span><button class="text-link" data-action="resource" data-id="${r.id}">Читать ${icon('arrow',14)}</button></div></article>`).join(''):empty(libraryFilter==='saved'?'Ваша коллекция начинается здесь':'Материалы не найдены',libraryFilter==='saved'?'Нажмите на закладку у понравившегося материала.':'Попробуйте другое название или категорию.')}
function libraryPage(){return pageHeading('Библиотека знаний','Всё, что стоит держать под рукой: справочники, статьи и полезные материалы.')+`<div class="toolbar"><div class="chips">${[['all','Все материалы'],['saved',`Избранное · ${state.bookmarks.length}`],['Шпаргалка','Шпаргалки'],['Справочник','Справочники'],['Статья','Статьи'],['Гайд','Гайды']].map(([id,label])=>`<button class="chip ${libraryFilter===id?'active':''}" data-action="library-filter" data-id="${id}">${label}</button>`).join('')}</div><input type="search" id="library-search" placeholder="Найти материал…" aria-label="Поиск материалов" value="${escapeHTML(libraryQuery)}"></div><div class="library-grid" id="library-grid">${resourceCards()}</div>`}
function settingsPage(){return pageHeading('Настройки','Сделайте это пространство своим.')+`<div class="settings-layout"><div class="panel settings-tabs">${[['profile','Мой профиль'],['appearance','Внешний вид'],['notifications','Уведомления'],['learning','Обучение'],['data','Данные и доступ']].map(([id,label])=>`<button class="settings-tab ${settingsTab===id?'active':''}" data-action="settings-tab" data-id="${id}">${label}</button>`).join('')}</div><section class="panel settings-content">${settingsContent()}</section></div>`}
function settingsContent(){if(settingsTab==='profile')return `<h2>Личная информация</h2><p>Так вас будут видеть в профиле и сертификатах.</p><div class="profile-edit"><span class="avatar">${escapeHTML(state.profile.name.slice(0,1)+state.profile.surname.slice(0,1))}</span><div><h3>${escapeHTML(state.profile.name+' '+state.profile.surname)}</h3><small>На пути к новым знаниям с сентября 2026</small></div></div><form id="profile-form"><div class="form-grid"><label class="field">Имя<input name="name" required maxlength="30" value="${escapeHTML(state.profile.name)}" autocomplete="given-name"></label><label class="field">Фамилия<input name="surname" required maxlength="40" value="${escapeHTML(state.profile.surname)}" autocomplete="family-name"></label><label class="field full">Электронная почта<input type="email" name="email" required value="${escapeHTML(state.profile.email)}" autocomplete="email"><small>В демоверсии письма не отправляются.</small></label><label class="field full">О себе<textarea name="bio" maxlength="300">${escapeHTML(state.profile.bio)}</textarea><small>До 300 символов</small></label></div><div class="form-actions"><button type="reset" class="button secondary">Отменить</button><button type="submit" class="button primary">Сохранить изменения</button></div></form>`;
if(settingsTab==='appearance')return `<h2>Внешний вид</h2><p>Выберите тему, в которой вам комфортно учиться.</p><div class="theme-choices">${['light','dark'].map(t=>`<button class="theme-choice ${state.theme===t?'selected':''}" data-action="set-theme" data-id="${t}" aria-pressed="${state.theme===t}"><div class="theme-preview ${t==='dark'?'dark':''}"></div><span>${t==='light'?'☀ Светлая':'☾ Тёмная'}</span></button>`).join('')}</div><div class="chart-note">${icon('sun',22)}<div><b>Всегда под рукой</b><p>Тему можно переключить кнопкой солнца в верхней панели.</p></div></div>`;
if(settingsTab==='notifications')return `<h2>Ваши уведомления</h2><p>Настройки сохраняются локально. Отправка писем появится после подключения бэкенда.</p>${[['reminders','Напоминания об обучении','Не забывайте о своей ежедневной цели.'],['achievements','Новые достижения','Сообщать об открытых наградах и завершении курсов.'],['digest','Еженедельный дайджест','Подборка материалов и ваш прогресс за неделю.']].map(([id,title,desc])=>`<div class="setting-row"><div><h3>${title}</h3><p>${desc}</p></div><button class="toggle ${state.preferences[id]?'on':''}" role="switch" aria-checked="${state.preferences[id]}" aria-label="${title}" data-action="preference" data-id="${id}"></button></div>`).join('')}`;
if(settingsTab==='learning')return `<h2>Учитесь в своём ритме</h2><p>Небольшие регулярные занятия лучше редких марафонов.</p><form id="learning-form"><div class="form-grid"><label class="field">Ежедневная цель<select name="goal">${['15','30','45','60'].map(v=>`<option value="${v}" ${state.profile.goal===v?'selected':''}>${v} минут в день</option>`).join('')}</select></label><label class="field">Дней в неделю<select name="weeklyGoal">${[3,4,5,6,7].map(v=>`<option value="${v}" ${state.weeklyGoal===v?'selected':''}>${v} дней</option>`).join('')}</select></label></div><div class="chart-note">${icon('fire',24)}<div><b>Ваша текущая серия — 12 дней</b><p>Каждый день — ещё один шаг к вашей цели.</p></div></div><div class="form-actions"><button class="button primary" type="submit">Сохранить цель</button></div></form>`;
return `<h2>Данные и доступ</h2><p>Это демонстрационный профиль. Данные хранятся только в этом браузере.</p><div class="setting-row"><div><h3>Ваш тариф: ${state.premium?'Premium Demo':'Бесплатный'}</h3><p>${state.premium?'Все демонстрационные возможности активны.':'Все базовые курсы и практика уже доступны.'}</p></div><button class="button soft" data-action="premium">${state.premium?'Управлять':'Подробнее'}</button></div><div class="setting-row"><div><h3>Экспорт данных</h3><p>Скачайте профиль, прогресс и сохранённые материалы в JSON.</p></div><button class="button secondary" data-action="export">${icon('download',15)}Экспорт</button></div><div class="setting-row"><div><h3>Начать заново</h3><p>Вернуть демонстрационные данные в исходное состояние.</p></div><button class="button danger" data-action="reset">Сбросить</button></div>`}

function lessonPage(){return '<div class="panel lesson-loading" role="status">'+icon('book',30)+'<h2>Открываем урок…</h2><p>Загружаем теорию и практику.</p></div>';}
function taskPage(id){const task=tasks.find(t=>t.id===id);if(!task)return notFound();return `<div class="breadcrumb"><a href="#/tasks">Практика</a>${icon('chevron',12)}<span>${task.title}</span></div><div class="task-layout"><article class="panel task-description"><h1 style="font-size:24px">${task.title}</h1><span class="badge ${task.level==='Лёгкая'?'green':'purple'}">${task.level}</span> <span class="badge gray">+${task.xp} XP</span><div class="prose"><h3>Условие</h3><p>${task.description}</p><h3>Пример</h3><pre class="code-block">${escapeHTML(task.example)}</pre><h3>Требования</h3><p>Объявите функцию <b>${task.fn}(${task.args})</b>. Верните результат через return. В релизе решение проверит сервер</p><p>${LKApi.mode==='mock'?'Проект ещё в разработке, можно написать и сохранить черновик':'Отправьте решение и получите результат проверки'}</p></div><button class="button soft" data-action="hint" data-id="${id}" style="margin-top:20px">${icon('help',16)}Нужна подсказка</button></article><section class="panel"><div class="editor-toolbar"><span>${icon('code',15)} solution.js</span><span>JavaScript ES2022</span><button class="icon-button" data-action="reset-code" data-id="${id}" aria-label="Восстановить шаблон">${icon('refresh',15)}</button></div><label class="sr-only" for="code-editor">Ваше решение JavaScript</label><textarea id="code-editor" class="code-editor" spellcheck="false" autocapitalize="off" autocomplete="off" data-task="${id}">${escapeHTML(state.drafts[id]??task.starter)}</textarea><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:12px"><small style="color:var(--muted)">Черновик сохраняется автоматически</small><button class="button primary" data-action="submit-task" data-id="${id}">${icon('play',15)}Отправить на проверку</button></div><div id="test-results" class="test-result" aria-live="polite">${state.solved.includes(id)?'✓ Вы уже решили эту задачу. Можно потренироваться ещё раз.':'Здесь появится ответ сервера, Ctrl + Enter отправляет решение'}</div></section></div>`}
function notFound(){return '<div class="not-found"><h1>404</h1><h2>Кажется, здесь ещё нет урока</h2><p>Вернёмся туда, где вас ждут новые знания.</p><a class="button primary" href="#/home">На главную</a></div>'}
function render(){if(!coursesReady)return;window.LKLesson.dispose();window.LKTask.dispose();closeModal();const [page='home',id,index]=(location.hash.replace(/^#\/?/,'')||'home').split('/');const navPage=(page==='lesson'||page==='course')?'courses':page==='task'?'tasks':page==='activity'?'home':page;$('#navigation').innerHTML=navItems.map(([key,label,kind])=>`<a class="nav-link ${navPage===key?'active':''}" href="#/${key}" ${navPage===key?'aria-current="page"':''}>${icon(kind,19)}<span>${label}</span></a>`).join('');const pages={home:homePage,courses:coursesPage,tasks:tasksPage,certificates:certificatesPage,achievements:achievementsPage,library:libraryPage,settings:settingsPage,activity:()=>pageHeading('Ваша активность','Каждое действие приближает вас к цели.')+`<section class="panel activity-full">${[...state.activity,...initialActivity].map(activityHTML).join('')}</section>`};$('#main').innerHTML=(page==='lesson'||page==='course')?lessonPage():page==='task'?taskPage(id):(pages[page]||notFound)();document.title=`${navItems.find(i=>i[0]===navPage)?.[1]||'Обучение'} — LogicKernel`;$('.sidebar').classList.remove('open');updateHeader();if(page==='lesson')window.LKLesson.mount(id,index);if(page==='course')window.LKLesson.mountCourse(id);}

function openModal(title,body,wide=false){closeModal();lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Закрыть">${icon('close',20)}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal input, .modal button, .modal a')?.focus())}
function closeModal(){if(modalCleanup){modalCleanup();modalCleanup=null}if($('#modal-root').innerHTML){$('#modal-root').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();lastFocus=null}}
function openSearch(){openModal('Поиск','');$('.modal').className='modal search-modal';$('.modal').innerHTML=`<div class="search-input-wrap">${icon('search',21)}<input id="global-search" placeholder="Что хотите изучить?" aria-label="Поиск по всей платформе" autocomplete="off"><button class="icon-button" data-action="close-modal" aria-label="Закрыть">${icon('close',18)}</button></div><h2 id="modal-title" class="sr-only">Поиск по платформе</h2><div class="search-results" id="search-results"></div><div class="search-help">Курсы, практические задачи и материалы · Esc — закрыть</div>`;searchResults('');requestAnimationFrame(()=>$('#global-search')?.focus())}
function searchResults(query){const q=query.toLowerCase().trim();const all=[...courses.map(c=>({title:c.subtitle,type:'Курс · '+c.level,route:`#/lesson/${c.id}`,kind:'book'})),...tasks.map(t=>({title:t.title,type:'Задача · JavaScript',route:`#/task/${t.id}`,kind:'code'})),...resources.map(r=>({title:r.title,type:r.type,id:r.id,kind:'file'}))];const found=all.filter(x=>(x.title+' '+x.type).toLowerCase().includes(q)).slice(0,q?14:6);$('#search-results').innerHTML=found.length?found.map(x=>`<${x.route?'a':'button'} class="search-result" ${x.route?`href="${x.route}"`:`data-action="resource" data-id="${x.id}"`}><span class="result-icon">${icon(x.kind,18)}</span><span><b>${escapeHTML(x.title)}</b><small>${x.type}</small></span>${icon('arrow',15)}</${x.route?'a':'button'}>`).join(''):empty('Ничего не найдено','Попробуйте «Python», «массивы» или «Go».')}
function openPremium(){openModal(state.premium?'Ваш Premium':'Учитесь без ограничений',`<div class="premium-modal"><div class="achievement-medal">${icon('crown',33)}</div><span class="badge">LOGICKERNEL PREMIUM</span><h3 style="margin-top:10px">Больше знаний. Больше возможностей.</h3><p>Всё для следующего шага в программировании — в одном месте.</p><div class="plan-price">990 ₽ <small>/ месяц</small></div><div class="plan-features">${['Все курсы и новые программы','Дополнительные проекты для портфолио','Материалы и сертификаты','Персональная поддержка наставника'].map(t=>`<div>${icon('check',18)}${t}</div>`).join('')}</div><button class="button ${state.premium?'secondary':'primary'}" style="width:100%" data-action="${state.premium?'cancel-premium':'activate-premium'}">${state.premium?'Отключить демо-Premium':'Попробовать Premium в деморежиме'}</button><p class="demo-note">Демонстрация интерфейса подписки. Оплата не производится, банковская карта не требуется. Поддержка наставника пока не подключена.</p></div>`)}
function download(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function certificateDownload(id){const course=courses.find(c=>c.id===id);if(id!=='intro'&&(!course||progress(course)!==100))return;const title=course?.subtitle||'Введение в программирование';const name=escapeHTML(state.profile.name+' '+state.profile.surname);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="850" viewBox="0 0 1200 850"><rect width="1200" height="850" fill="#fffdf5"/><rect x="30" y="30" width="1140" height="790" rx="6" fill="white" stroke="#ffdc00" stroke-width="3"/><rect x="45" y="45" width="1110" height="760" fill="none" stroke="#eee6b9"/><path d="M30 30h300L30 330Z" fill="#ffdc00" opacity=".08"/><g font-family="Arial,sans-serif" text-anchor="middle"><text x="600" y="145" font-size="38" fill="#252738">&lt;/&gt; Logic<tspan fill="#d5b700">Kernel</tspan></text><text x="600" y="265" font-size="47" letter-spacing="10" fill="#252738">СЕРТИФИКАТ</text><text x="600" y="320" font-size="19" fill="#878a99">о прохождении учебного курса</text><text x="600" y="430" font-size="38" fill="#252738">${name}</text><text x="600" y="495" font-size="20" fill="#878a99">успешно завершил(а) курс</text><text x="600" y="550" font-size="29" fill="#252738">${escapeHTML(title)}</text><path d="M400 590h400" stroke="#ffdc00" stroke-width="3"/><text x="600" y="665" font-size="16" fill="#878a99">${new Date().toLocaleDateString('ru-RU')} · LK-DEMO-${id.toUpperCase()}</text><text x="600" y="750" font-size="13" fill="#999">Демонстрационный сертификат платформы LogicKernel</text></g></svg>`;download(`LogicKernel-сертификат-${id}.svg`,svg,'image/svg+xml;charset=utf-8');toast('Сертификат скачан в формате SVG')}

// A worker created inside an opaque-origin sandbox runs the student's code.
// The CSP blocks network access; termination also stops infinite loops.
document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#/"]');if(link){closeModal();if(link.getAttribute('href')===location.hash){render();window.scrollTo(0,0)}}const target=event.target.closest('[data-action]');if(!target)return;const {action,id,index}=target.dataset;
switch(action){case 'retry-bootstrap':bootstrapCourses();break;case 'sidebar':$('.sidebar').classList.toggle('open');break;case 'theme':state.theme=state.theme==='light'?'dark':'light';save();updateHeader();if(location.hash==='#/settings'&&settingsTab==='appearance')render();break;case 'set-theme':state.theme=id;save();render();break;case 'search':openSearch();break;case 'close-modal':closeModal();break;
case 'profile':openModal('Ваш профиль',`<div class="profile-edit"><span class="avatar">${escapeHTML(state.profile.name[0]+state.profile.surname[0])}</span><div><h3>${escapeHTML(state.profile.name+' '+state.profile.surname)}</h3><small>${escapeHTML(state.profile.email)}</small></div></div><div class="profile-menu"><a href="#/settings">${icon('settings')}Настройки профиля</a><a href="#/achievements">${icon('trophy')}Достижения <span class="xp">${state.xp} XP</span></a><a href="#/certificates">${icon('award')}Мои сертификаты</a></div>`);break;
case 'notifications':openModal('Уведомления',`<div class="notification-item"><span class="activity-icon yellow">${icon('fire')}</span><div><h3>12 дней на пути к цели!</h3><p>Продолжите обучение сегодня и сохраните свой ритм.</p></div></div><div class="notification-item"><span class="activity-icon">${icon('circleCheck')}</span><div><h3>Ваш прогресс сохранён</h3><p>Уроки, решения и избранное доступны в этом браузере.</p></div></div>${state.activity.slice(0,3).map(a=>`<div class="notification-item"><span class="activity-icon yellow">${icon(a.icon)}</span><div><h3>${escapeHTML(a.title)}</h3><p>Вы получили +${a.xp} XP</p></div></div>`).join('')}<div class="form-actions"><button class="button primary" data-action="read-notifications">Отметить всё прочитанным</button></div>`);break;
case 'read-notifications':state.notificationsRead=true;save();updateHeader();closeModal();toast('Все уведомления прочитаны');break;
case 'premium':openPremium();break;case 'activate-premium':state.premium=true;save();updateHeader();closeModal();toast('Демо-Premium активирован. Оплата не требуется.');if(location.hash==='#/settings')render();break;case 'cancel-premium':state.premium=false;save();updateHeader();closeModal();toast('Демо-Premium отключён');if(location.hash==='#/settings')render();break;
case 'course-filter':courseFilter=id;render();break;case 'task-filter':taskFilter=id;render();break;case 'library-filter':libraryFilter=id;render();break;case 'settings-tab':settingsTab=id;render();break;
case 'enroll':if(!state.enrolled.includes(id)){state.enrolled.push(id);save();toast('Курс добавлен в ваше обучение')}location.hash=`#/lesson/${id}/0`;break;
case 'course-info':location.hash='#/course/'+id;break;case 'legacy-course-info':{const c=courses.find(c=>c.id===id);openModal(c.subtitle,`<div class="course-logo" style="height:70px">${logo(id)}</div><p class="modal-description">${escapeHTML(c.description)}</p><div class="catalog-meta"><span>${icon('book',16)}${c.lessons} уроков</span><span>${icon('clock',16)}${c.hours} часов</span><span>${escapeHTML(c.level)}</span></div><p class="modal-description">Автор курса: ${escapeHTML(c.teacher)}. В курсе ${c.lessons} уроков с редактором, практикой и проектными работами</p><div class="form-actions"><a class="button primary" href="#/lesson/${id}">Перейти к обучению ${icon('arrow',15)}</a></div>`);break;}
case 'bookmark':state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();$('#library-grid').innerHTML=resourceCards();$$('[data-action="library-filter"]').find(b=>b.dataset.id==='saved').textContent=`Избранное · ${state.bookmarks.length}`;toast(state.bookmarks.includes(id)?'Материал добавлен в избранное':'Материал удалён из избранного');break;
case 'resource':{const r=resources.find(r=>r.id===id);openModal(r.title,`<div class="lesson-meta"><span>${r.type}</span><span>${r.time} чтения</span></div><article class="prose">${r.body}</article><div class="form-actions"><button class="button secondary" data-action="download-resource" data-id="${id}">${icon('download',15)}Скачать материал</button><button class="button primary" data-action="close-modal">Понятно</button></div>`,true);break;}
case 'download-resource':{const r=resources.find(r=>r.id===id);const el=document.createElement('div');el.innerHTML=r.body.replace(/<\/(h3|p|pre|li|div)>/g,'</$1>\n\n');download(`${r.id}.txt`,r.title+'\n\n'+el.textContent,'text/plain;charset=utf-8');toast('Материал скачан');break;}
case 'certificate':certificateDownload(id);break;case 'preference':state.preferences[id]=!state.preferences[id];save();target.classList.toggle('on',state.preferences[id]);target.setAttribute('aria-checked',state.preferences[id]);toast('Настройка сохранена');break;
case 'export':download('logickernel-data.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Данные экспортированы');break;
case 'reset':openModal('Начать заново?',`<p class="modal-description">Ваши новые решения, пройденные уроки, избранное и изменения профиля будут удалены из этого браузера. Вернутся исходные демонстрационные данные.</p><div class="form-actions"><button class="button secondary" data-action="close-modal">Отмена</button><button class="button danger" data-action="confirm-reset">Сбросить данные</button></div>`);break;
case 'confirm-reset':state=structuredClone(defaults);state.lessonDrafts={};state.lessonReads=[];state.lessonChecks={};state.curriculumVersion='2026.09.14.1';save();closeModal();render();toast('Восстановлены исходные данные');break;
case 'hint':{const t=tasks.find(t=>t.id===id);openModal('Небольшая подсказка',`<p class="modal-description">${t.hint}</p><div class="form-actions"><button class="button primary" data-action="close-modal">Попробую решить</button></div>`);break;}
case 'reset-code':openModal('Восстановить шаблон?',`<p class="modal-description">Ваш текущий код будет заменён исходным шаблоном задачи.</p><div class="form-actions"><button class="button secondary" data-action="close-modal">Отмена</button><button class="button primary" data-action="confirm-code-reset" data-id="${id}">Восстановить</button></div>`);break;
case 'confirm-code-reset':state.drafts[id]=tasks.find(t=>t.id===id).starter;save();closeModal();$('#code-editor').value=state.drafts[id];$('#test-results').className='test-result';$('#test-results').textContent='Шаблон восстановлен. Готовы к новой попытке?';break;
case 'submit-task':LKTask.submit(tasks.find(t=>t.id===id));break;
}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='global-search')searchResults(el.value);if(el.id==='course-search'){courseQuery=el.value;$('#catalog-grid').innerHTML=catalogCards()}if(el.id==='library-search'){libraryQuery=el.value;$('#library-grid').innerHTML=resourceCards()}if(el.id==='code-editor'){state.drafts[el.dataset.task]=el.value;save()}});
document.addEventListener('change',event=>{if(event.target.id==='chart-course'){const c=courses.find(c=>c.id===event.target.value);$('#chart-container').innerHTML=chartHTML(c);$('#chart-title').textContent='Прогресс курса: '+c.subtitle;$('#chart-logo').innerHTML=logo(c.id)}});
document.addEventListener('submit',event=>{if(event.target.id==='profile-form'){event.preventDefault();const data=new FormData(event.target);const name=String(data.get('name')).trim(),surname=String(data.get('surname')).trim();if(!name||!surname){toast('Введите имя и фамилию');return}state.profile={...state.profile,name,surname,email:String(data.get('email')).trim(),bio:String(data.get('bio')).trim()};save();render();toast('Профиль обновлён')}if(event.target.id==='learning-form'){event.preventDefault();const data=new FormData(event.target);state.profile.goal=data.get('goal');state.weeklyGoal=Number(data.get('weeklyGoal'));save();toast('Цель обучения сохранена')}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch()}if(event.key==='Escape'){closeModal();$('.sidebar').classList.remove('open')}if(event.target.id==='code-editor'&&event.key==='Tab'){event.preventDefault();const el=event.target;const start=el.selectionStart;el.setRangeText('  ',start,el.selectionEnd,'end');state.drafts[el.dataset.task]=el.value;save()}if((event.ctrlKey||event.metaKey)&&event.key==='Enter'&&$('#code-editor')&&!$('.modal')){event.preventDefault();if(!$('[data-action="submit-task"]').disabled)LKTask.submit(tasks.find(t=>t.id===$('#code-editor').dataset.task))}if(event.key==='Tab'&&$('.modal')){const elements=$$('button:not(:disabled),a[href],input,select,textarea,summary,[tabindex="0"]',$('.modal')).filter(el=>el.getClientRects().length);if(!elements.length)return;const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
$('#modal-root').addEventListener('click',event=>{if(event.target.classList.contains('modal-backdrop'))closeModal()});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});
$('.mobile-menu').innerHTML=icon('menu',21);$('.search-symbol').innerHTML=icon('search',17);$('.profile-chevron').innerHTML=icon('down',13);$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon,15));
async function bootstrapCourses(){
  $('#main').innerHTML='<div class="panel lesson-loading" role="status">'+icon('book',30)+'<h2>Загружаем курсы…</h2></div>';
  try {const response=await LKApi.listCourses();if(!Array.isArray(response.data))throw new Error('Некорректный каталог');courses.splice(0,courses.length,...response.data);state.enrolled=state.enrolled.filter(id=>courses.some(c=>c.id===id));coursesReady=true;render();}
  catch(error){$('#main').innerHTML='<div class="panel lesson-loading"><h2>Не удалось загрузить курсы</h2><p>'+escapeHTML(error.message)+'</p><button class="button primary" data-action="retry-bootstrap">Повторить</button></div>';}
}
bootstrapCourses();
